{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/lab",
  "data": {
    "name": "DialogHeroHeader",
    "displayName": "Dialog Hero Header",
    "import": "@astryxdesign/lab",
    "group": "DialogHeroHeader",
    "category": "Overlay",
    "keywords": [
      "dialog",
      "modal",
      "header",
      "hero",
      "media",
      "image",
      "illustration",
      "onboarding",
      "marketing",
      "featured",
      "close button",
      "title"
    ],
    "description": "Experimental hero-style header for Dialog, available from @astryxdesign/lab@canary: a full-bleed media slot above the title with the close button overlaid on the media. The high-emphasis sibling of DialogHeader for featured, marketing, or onboarding dialogs.",
    "props": [
      {
        "name": "title",
        "type": "string | ReactElement",
        "description": "Dialog title. A string is wrapped in a level 2 Heading (matching DialogHeader); pass a pre-styled Heading element to customize the treatment. Provides the accessible label for the parent Dialog via aria-labelledby unless the Dialog has an explicit label. The visible title is the default initial focus target; another eligible descendant autofocus request takes priority. A custom Heading receives the label and focus on its own element; if it sets its own id, name the Dialog with aria-labelledby.",
        "required": true
      },
      {
        "name": "media",
        "type": "ReactNode",
        "description": "Full-bleed visual rendered above the title (image, illustration, or icon). Stretches to the dialog's padded edges; the close button overlays its top-trailing corner. Size the media itself (e.g. width 100%) to fill the slot.",
        "required": true
      },
      {
        "name": "mediaMode",
        "type": "'light' | 'dark'",
        "description": "Luminance of the media surface. Composes MediaTheme under the hood so content overlaid on the media (the close button) picks up contrast-safe inverted tokens: 'dark' media gets light overlay content, 'light' media gets dark. Omit to keep ambient theme tokens."
      },
      {
        "name": "isTitleHidden",
        "type": "boolean",
        "description": "Visually hides the title row while keeping it available to screen readers, so the dialog stays named by the title.",
        "default": "false"
      },
      {
        "name": "startContent",
        "type": "ReactNode",
        "description": "Content placed before the title (e.g. an icon), inline with the heading."
      },
      {
        "name": "maxLines",
        "type": "number",
        "description": "Max lines before the title truncates with an ellipsis. Only applies when title is a string (auto-wrapped in a Heading)."
      },
      {
        "name": "onOpenChange",
        "type": "(isOpen: boolean) => unknown",
        "description": "Close button callback, called with false when the close button is clicked. If not provided, no close button is rendered. Same contract as DialogHeader."
      },
      {
        "name": "hasDivider",
        "type": "boolean",
        "description": "Adds a themed border at the bottom edge. Defaults to the parent Layout's defaultHasDividers context value."
      }
    ],
    "usage": {
      "description": "Drop into Layout's header slot inside a Dialog, exactly like DialogHeader. Use when the dialog opens onto a featured, marketing, or onboarding moment where the compact DialogHeader is too understated. The media bleeds to the dialog's edges automatically and the close button floats over its top-trailing corner. The visible title is the default initial focus target; inline previews do not move focus. Install @astryxdesign/lab@canary with @astryxdesign/core@canary and import both packages’ CSS. Lab APIs can change between canary versions.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Set mediaMode to match the media's luminance so the overlaid close button stays legible: dark imagery needs mediaMode=\"dark\"."
        },
        {
          "guidance": true,
          "description": "Size the media content to fill the slot (width 100% for images); the slot itself only positions and bleeds."
        },
        {
          "guidance": true,
          "description": "Keep actions (CTAs) in LayoutFooter; the hero header takes no actions slot."
        },
        {
          "guidance": true,
          "description": "Use isTitleHidden when the media already communicates the message visually; the title still names the dialog for screen readers."
        },
        {
          "guidance": false,
          "description": "Use for routine confirmations or forms; use the compact DialogHeader instead."
        },
        {
          "guidance": false,
          "description": "Pass decorative media without an empty alt: use alt=\"\" on purely decorative images so screen readers skip them."
        }
      ]
    },
    "examples": [
      {
        "label": "Onboarding dialog",
        "code": "import {DialogHeroHeader} from '@astryxdesign/lab';\nimport '@astryxdesign/core/astryx.css';\nimport '@astryxdesign/lab/lab.css';\n\nconst [isOpen, setIsOpen] = useState(true);\n<Dialog isOpen={isOpen} onOpenChange={setIsOpen}>\n  <Layout\n    header={\n      <DialogHeroHeader\n        title=\"Welcome aboard\"\n        media={<img src={heroImage} alt=\"\" width=\"100%\" />}\n        mediaMode=\"dark\"\n        onOpenChange={setIsOpen}\n      />\n    }\n    content={<LayoutContent>Get started in three steps.</LayoutContent>}\n    footer={\n      <LayoutFooter hasDivider>\n        <Button label=\"Get started\" variant=\"primary\" />\n      </LayoutFooter>\n    }\n  />\n</Dialog>"
      },
      {
        "label": "Hidden title (media carries the message)",
        "code": "<DialogHeroHeader\n  title=\"Product tour\"\n  media={<AnnouncementIllustration />}\n  isTitleHidden\n  onOpenChange={setIsOpen}\n/>"
      }
    ],
    "package": "@astryxdesign/lab",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
